<script setup lang="ts">
import { computed, ref } from 'vue'
import { useSimulationStore } from '@/stores/simulation'
import AppIcon from '@/components/AppIcon.vue'
const sim = useSimulationStore()
const search = ref(''), level = ref('all')
const filtered = computed(() => sim.events.filter(event => (level.value === 'all' || event.level === level.value) && `${event.robot} ${event.message}`.toLowerCase().includes(search.value.toLowerCase())))
</script>
<template><div class="page-heading"><div><h1>运行日志<span class="accent">.</span></h1><p>追踪每一条控制指令，以及它在仿真中的执行结果。</p></div><button class="btn btn-ghost" :disabled="!sim.events.length" @click="sim.events = []"><AppIcon name="reset" />清空日志</button></div><div class="log-filter"><label class="field"><input v-model="search" aria-label="搜索日志" placeholder="搜索机器人或指令内容…"></label><div class="segmented"><button v-for="option in [{ id: 'all', label: '全部' }, { id: 'info', label: '信息' }, { id: 'warning', label: '警告' }]" :key="option.id" :class="{ active: level === option.id }" @click="level = option.id">{{ option.label }}</button></div><span class="muted">{{ filtered.length }} 条记录</span></div><div class="panel"><div v-if="filtered.length" class="table-scroll"><table class="data-table"><thead><tr><th>本地时间</th><th>级别</th><th>机器人</th><th>事件</th></tr></thead><tbody><tr v-for="event in filtered" :key="event.id"><td class="mono muted">{{ event.time }}</td><td><span class="event-level" :class="event.level"><i class="dot" />{{ event.level === 'warning' ? '警告' : '信息' }}</span></td><td class="mono">{{ event.robot }}</td><td>{{ event.message }}</td></tr></tbody></table></div><div v-else class="empty-state"><AppIcon name="log" /><h3>{{ sim.events.length ? '没有匹配的运行记录' : '运行日志已清空' }}</h3><p>{{ sim.events.length ? '尝试其他关键词或切换日志级别。' : '下一次执行动作或控制指令时，记录将显示在这里。' }}</p><RouterLink class="btn btn-ghost" :to="`/${sim.selectedId}`">返回工作台</RouterLink></div></div><p class="log-note">日志仅保留当前会话最近 100 条记录，刷新页面后清空。所有事件均来自本地仿真。</p></template>
<style scoped lang="less">.log-filter { display: flex; align-items: center; gap: 14px; margin-bottom: 20px; .field { flex: 1; max-width: 360px; } > span { margin-left: auto; font-size: 10px; } }.event-level { display: inline-flex; align-items: center; gap: 6px; color: #a6c984; font-size: 10px; &.warning { color: var(--warning); } }.log-note { margin-top: 18px; color: var(--faint); font-size: 10px; line-height: 1.8; }.data-table { min-width: 650px; }@media(max-width:650px) { .log-filter { flex-wrap: wrap; .field { flex-basis: 100%; max-width: none; } } }</style>
